def ColourTextSquare(x,y,mytext,charwidth,size):  # only use Square for REALLY big text
    return LEDlib.LEDtextobj(canvas1,x=x,y=y,text=mytext,colour="light green",pixelsize = size, charwidth=charwidth, solid = False, square=True)

def ColourTextSquareRed(x,y,mytext,charwidth,size):  # only use Square for REALLY big text
    return LEDlib.LEDtextobj(canvas1,x=x,y=y,text=mytext,colour="red",pixelsize = size, charwidth=charwidth, solid = False, square=True)


def ColourText(x,y,mytext,charwidth,size):
    return LEDlib.LEDtextobj(canvas1,x=x,y=y,text=mytext,colour="light green",pixelsize = size, charwidth=charwidth, solid = False, square=False)

def smalltext(x,y,mytext):
    return ColourText(x,y,mytext,8*2-2,2)

def medtext(x,y,mytext):
    return ColourText(x,y,mytext,8*3,3)

def sind(x):
    return math.sin(math.radians(x))

def cosd(x):
    return math.cos(math.radians(x))

def tand(x):
    return math.tan(math.radians(x))

def screenx(x): # converts real x position to a screen position
    return int(x*scalex)+xoffset

def screeny(y): # converts real y position to a screen position
    return int(groundy-y*scaley)

#endregion




#region Physics functions
def resetball():
    global ballx0, bally0, vx, vy, v
    v = math.sqrt(r*g)
    ballx0 = gunx
    bally0 = guny
    vx = v*cosd(angle) # x component of initial velocity
    vy = v*sind(angle) # y component of initial velocity
    ball.resetposition(screenx(ballx0)-15+8, screeny(bally0)-10) # ball is a big 8 by 8 square with a dot in it!!!!
    ball.undraw()
    intialvelocitytext.update(int(v))


def moveball():
    global ballx, bally, gamestate
    ballx  = vx*tm + ballx0
    bally = -0.5*g*tm**2+vy*tm+bally0
    ball.resetposition(screenx(ballx)-15+8, screeny(bally)-10)
    xtext.update(int(ballx))
    vxtext.update(int(vx))
    vytext.update(int(abs(-g*tm+vy)))
    if bally >= 0: 
         ytext.update(int(bally))
    else:
         ytext.update(0) 
         b = angle
         b2 = 2 * b / 57.3; # convert b to radians
         i0 = r * math.sin(b2)
         xtext.update(int(abs(i0))) # true distance covered by shell
         vxtext.update(0)
         vytext.update(0)
         bally=0
         ball.resetposition(screenx(ballx)-15+8, screeny(bally)-10)
         gamestate = GameStates.IMPACT
#endregion

