#region buttons
def onclickFire():
    global s, z, ballx, bally, tm, gamestate
    gamestate = GameStates.PROJECTILEFLYING
    statustext.update("Shell Fired. Waiting for impact")
    tm = 0
    ballx = ballx0
    bally = bally0
    resetball()
    timer1()
    s = s + 1
    b = angle
    b2 = 2 * b / 57.3; # convert b to radians
    i0 = r * math.sin(b2)
    print("True distance = ", i0)
    e = int(t - i0);
    if (abs(e) < 100):
       RetroScreen.scrollboxadd("*** Target destroyed *** "+str(s)+ " rounds of ammunition expended")
       enemyhit = True;
       z = z + 1
       if (z < 4):
         RetroScreen.scrollboxadd("The forward observer has sighted more enemy activity...")
    elif (e < 0):
         RetroScreen.scrollboxadd("Over target by " + str(abs(e))+ " metres")
    else:   
         RetroScreen.scrollboxadd("Short of target by " + str(abs(e))+ " metres")

def updateangle(mystep):
    global angle
    angle = angle + mystep
    if angle > 89: angle = 89
    if angle < 5: angle = 5
    retroangletext.update(angle)
    resetball()
    n = len(GunList)
    i = int((n-1)*angle/90)
    gun.loadchar(GunList[(n-1)-i])

def onclickPlus(): updateangle(0.1)
def onclickPlusPlus(): updateangle(1)
def onclickMinusMinus(): updateangle(-1)
def onclickMinus(): updateangle(-0.1)


